@app.route('/median', methods=['POST'])
def median():
    data = request.get_json()
    if 'numbers' not in data or not isinstance(data['numbers'], list):
        return jsonify({'message': 'Invalid input'}), 400

    numbers = data['numbers']

    if len(numbers) == 0:
        return jsonify({'message': 'No numbers provided'}), 400

    # Calculate median
    sorted_numbers = sorted(numbers)
    mid = len(sorted_numbers) // 2

    if len(sorted_numbers) % 2 == 0:
        median_value = (sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2
    else:
        median_value = sorted_numbers[mid]

    return jsonify({'message': median_value}), 200

