class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def compute_tree(root):
    if root is None:
        return 0

    if isinstance(root.val, (int, float)):
        return root.val

    left_value = compute_tree(root.left)
    right_value = compute_tree(root.right)

    if root.val == '+':
        return left_value + right_value
    elif root.val == '-':
        return left_value - right_value
    elif root.val == '*':
        return left_value * right_value
    elif root.val == '/':
        if right_value == 0:
            raise ZeroDivisionError("division by zero")
        return left_value / right_value
    elif root.val == '^':
        return left_value ** right_value
    elif root.val == '%':
        return left_value % right_value

    raise ValueError(f"Invalid operator: {root.val}")

