import ast

app = Flask(__name__)

@app.route('/execute', methods=['POST'])
def execute_data():
    code = request.form.get('code')
    if code:
        try:
            # Safely evaluate the code using ast
            tree = ast.parse(code)
            allowed_nodes = (ast.Expression, ast.Str, ast.Num, ast.List, ast.Dict, ast.Tuple, ast.Name, ast.Load)
            for node in ast.walk(tree):
                if not isinstance(node, allowed_nodes):
                    return 'Unauthorized code execution', 403

            exec(compile(tree, filename="<ast>", mode="eval"))
            return 'Executed'
        except Exception as e:
            return str(e), 400
    return 'No code provided', 400

